/** 首页聚合数据：通知公告 / 待办数 / 学习园地 / 新闻公告 / 横幅 */
export async function fetchHome(): Promise<PortalHomeData> {
  // 待办数量以「任务中心列表」真实总数为准：首页角标与点击进入后的列表条数必须一致。
  const [noticeRow, taskTotal, studyRows, newsRows, bannerRows] = await Promise.all([
    request(async () => (await api.appMsg({ pageNum: 1, pageSize: 1, msgType: '' })).rows[0] as Row | undefined, undefined).catch(() => undefined),
    request(async () => (await api.getTodoTaskList({ pageNum: 1, pageSize: 1 })).total as number, 0).catch(() => 0),
    request(async () => (await api.getStudyList({ tab: 1, pageNum: 1, pageSize: 2 })).rows as Row[], [] as Row[]).catch(() => [] as Row[]),
    request(async () => (await api.articlePage({ pageNum: 1, pageSize: 3 })).rows as Row[], [] as Row[]).catch(() => [] as Row[]),
    request(async () => (await api.getBannerList({ pageNum: 1, pageSize: 1 })).rows as Row[], [] as Row[]).catch(() => [] as Row[]),
  ])

  const notice = noticeRow
    ? { id: first(noticeRow.msgId, noticeRow.id), title: first(noticeRow.msgTitle, noticeRow.title) }
    : { id: '', title: '' }
  const todoCount = num(taskTotal)
  const study = Object.fromEntries(PORTAL_TABS.map(t => [t, [] as PortalArticle[]]))
  if (studyRows.length) study[PORTAL_TABS[0]] = studyRows.slice(0, 2).map(r => toArticle(r))
  const news = newsRows.slice(0, 3).map(r => toArticle(r))
  const bannerRow = bannerRows[0]
  const banner = { small: first(bannerRow?.small), title: first(bannerRow?.title), sub: first(bannerRow?.sub, bannerRow?.subtitle), linkUrl: first(bannerRow?.linkUrl, bannerRow?.url) || undefined }

  return { notice, todoCount, todoText: '', banner, tabs: [...PORTAL_TABS], study, news }
}

tool_input.new_string:
/** 首页聚合数据：通知公告 / 待办数 / 学习园地 / 新闻公告 / 横幅 */
export async function fetchHome(): Promise<PortalHomeData> {
  // 待办数量与列表共用同一页结果：首页同步显示第一条真实待办。
  const [noticeRow, taskPage, studyRows, newsRows, bannerRows] = await Promise.all([
    request(async () => (await api.appMsg({ pageNum: 1, pageSize: 1, msgType: '' })).rows[0] as Row | undefined, undefined).catch(() => undefined),
    request(async () => await api.getTodoTaskList({ pageNum: 1, pageSize: 1 }), { total: 0, rows: [] as Row[] }).catch(() => ({ total: 0, rows: [] as Row[] })),
    request(async () => (await api.getStudyList({ tab: 1, pageNum: 1, pageSize: 2 })).rows as Row[], [] as Row[]).catch(() => [] as Row[]),
    request(async () => (await api.articlePage({ pageNum: 1, pageSize: 3 })).rows as Row[], [] as Row[]).catch(() => [] as Row[]),
    request(async () => (await api.getBannerList({ pageNum: 1, pageSize: 1 })).rows as Row[], [] as Row[]).catch(() => [] as Row[]),
  ])

  const notice = noticeRow
    ? { id: first(noticeRow.msgId, noticeRow.id), title: first(noticeRow.msgTitle, noticeRow.title) }
    : { id: '', title: '' }
  const todoCount = num(taskPage.total)
  const todoRow = taskPage.rows[0]
  const taskTitle = first(todoRow?.submitTittle, todoRow?.procDefName, todoRow?.taskName, todoRow?.name)
  const taskLocation = first(todoRow?.startDeptName, todoRow?.deptName)
  const todoText = taskTitle && taskLocation ? `${taskTitle}：${taskLocation}` : taskTitle || taskLocation
  const study = Object.fromEntries(PORTAL_TABS.map(t => [t, [] as PortalArticle[]]))
  if (studyRows.length) study[PORTAL_TABS[0]] = studyRows.slice(0, 2).map(r => toArticle(r))
  const news = newsRows.slice(0, 3).map(r => toArticle(r, 'article', true))
  const bannerRow = bannerRows[0]
  const banner = {
    small: first(bannerRow?.small, bannerRow?.organizationName),
    title: first(bannerRow?.title, bannerRow?.name),
    sub: first(bannerRow?.sub, bannerRow?.subtitle),
    image: resolveMedia(first(bannerRow?.pictureUrl, bannerRow?.imageUrl)) || undefined,
    linkUrl: first(bannerRow?.linkUrl, bannerRow?.url) || undefined,
  }

  return { notice, todoCount, todoText, banner, tabs: [...PORTAL_TABS], study, news }
}
